# old (English take) word index -> new (Urdu/Punjabi dialogue take) word index, line by line
LM=[(0,8,0,8),(9,18,9,18),(19,27,19,27),(28,33,28,34),(34,40,35,43),(41,48,44,54),(49,52,55,57),(53,58,58,63),(59,64,64,71),(65,70,72,77),(71,76,78,83),(77,79,84,86),(80,83,87,91),(84,88,92,101),(89,90,102,105),(91,93,106,109),(94,96,110,112),(97,99,113,115),(100,106,116,125),(107,115,126,139),(116,121,140,146),(122,127,147,152),(128,133,153,158),(134,140,159,165),(141,146,166,175),(147,149,176,180),(150,152,181,184),(153,155,185,187),(156,158,188,192),(159,164,193,198),(165,172,199,206),(173,176,207,210),(177,184,211,219)]
def remap_words(Wn):
    out=[]
    for a,b,c,d in LM:
        for i in range(a,b+1): out.append(Wn[c if i==a else d if i==b else round(c+(i-a)*(d-c)/max(1,b-a))])
    return out
